---GetTowerRewardPoolVo 爬塔随机奖池表
---@param groupId integer
function OverseaTowerUtils.GetTowerRewardPoolVo(groupId)
    if checkNumber(groupId) == 0 then
        return {}
    end
    local t = {}
    local pools = CfUtils.GetCf(AutoIds.IdSetting6021, "TowerRewardPoolVo", true)
    for i, v in pairs(pools) do
        if checkNumber(v.groupId) == checkNumber(groupId) then
            if not table.find(t, function(item)
                return checkNumber(item.goodsId) == checkNumber(v.itemID)
            end) then
                table.insert(t, {goodsId = checkNumber(v.itemID)})
            end
        end
    end
    return t
end

function OverseaTowerUtils.IsUnlockQuest(questId)
    ---@type TowerQuestVo
    local vo = OverseaTowerUtils.GetTowerQuestVo(questId) 
    if not vo then
        return false
    end
    ---@type TowerQuestComponent
    local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
    return towerQuestComponent:IsUnlockTowerQuest(vo.type, vo)
end

function OverseaTowerUtils.IsPassQuest(questId)
    local vo = OverseaTowerUtils.GetTowerQuestVo(questId) 
    if not vo then
        return false
    end

    ---@type TowerQuestComponent
    local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
    return towerQuestComponent:IsPassedQuest(vo.type, questId)
end

--第一层的关卡id
function OverseaTowerUtils.GetFirstQuestId(type)
    local t = OverseaTowerUtils.GetTypeData(type)
    if not t then
        return 0
    end
    return checkNumber(t[1])
end

function OverseaTowerUtils.GetAllTowerQuest(type)
    local t = OverseaTowerUtils.GetTypeData(type)
    local arg1Vo = OverseaTowerUtils.GetClimbTowerConfigVo(1) ---主塔
    local arg2Vo = OverseaTowerUtils.GetClimbTowerConfigVo(2) --副塔
    local maxLayer = 0
    if type == Constants.TowerType.Main then
        maxLayer = checkNumber(arg1Vo.num)
    else
        maxLayer = checkNumber(arg2Vo.num)
    end
    local ids = {}
    for i, v in pairs(t) do
        if i <= maxLayer then
            table.insert(ids, v)
        end
    end
    return ids
end
--最大层数
function OverseaTowerUtils.GetMaxQuestNum(type)
    local arg1Vo = OverseaTowerUtils.GetClimbTowerConfigVo(1) ---主塔
    local arg2Vo = OverseaTowerUtils.GetClimbTowerConfigVo(2) --副塔
    local maxLayer = 0
    if type == Constants.TowerType.Main then
        maxLayer = checkNumber(arg1Vo.num)
    else
        maxLayer = checkNumber(arg2Vo.num)
    end
    local t = OverseaTowerUtils.GetTypeData(type)
    if table.count(t) < maxLayer then
        return table.count(t)
    else
        return maxLayer
    end
end

--- 使用关卡id获取是否有下一层
---@param questId any
function OverseaTowerUtils.HasNextQuest(questId)
    local vo = OverseaTowerUtils.GetTowerQuestVo(questId)
    if isNotNull(vo) then
        local curLayer = vo.storey
        local maxLayer = OverseaTowerUtils.GetMaxQuestNum(vo.type)
        return curLayer < maxLayer
    else
        return false
    end
end

--- 获取塔的类型
---@param questId any
function OverseaTowerUtils.GetTowerType(questId)
    local vo = OverseaTowerUtils.GetTowerQuestVo(questId)
    if isNotNull(vo) then
        return vo.type
    else
        return nil
    end
end

function OverseaTowerUtils.GetMaxQuestId(type)
    local t = OverseaTowerUtils.GetTypeData(type)
    local arg1Vo = OverseaTowerUtils.GetClimbTowerConfigVo(1) ---主塔
    local arg2Vo = OverseaTowerUtils.GetClimbTowerConfigVo(2) --副塔
    local maxLayer = 0
    if type == Constants.TowerType.Main then
        maxLayer = checkNumber(arg1Vo.num)
    else
        maxLayer = checkNumber(arg2Vo.num)
    end
    local count = table.count(t)
    local len = math.min(count, maxLayer)
    return checkNumber(t[len])
end

function OverseaTowerUtils.GetTypeData(type)
    if  isNull(OverseaTowerUtils.QuestTypeData[type]) then
        local t = CfUtils.GetIdGroupData(AutoIds.IdSetting970, type)
        OverseaTowerUtils.QuestTypeData[type] = t
    end
    return OverseaTowerUtils.QuestTypeData[type]
end

--当前 正在打的关卡id (并不是已通关的)
function OverseaTowerUtils.GetCurQuestId(type)
    ---@type TowerQuestComponent
    local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
    local id = towerQuestComponent:GetCurrentQuestId(type)
    if checkNumber(id) <= 0 then
        return OverseaTowerUtils.GetFirstQuestId(type)
    end
    local vo = OverseaTowerUtils.GetTowerQuestVo(id)
    if checkNumber(vo.nextLevel) <= 0 then
        return id
    end
    local maxQuestId = OverseaTowerUtils.GetMaxQuestId(type)
    if checkNumber(vo.nextLevel) > maxQuestId then
        return maxQuestId
    end
    return vo.nextLevel
end


-- 已通关的 关卡id
function OverseaTowerUtils.GetPassedQuestId(type)
    ---@type TowerQuestComponent
    local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
    local id = towerQuestComponent:GetCurrentQuestId(type)
    if checkNumber(id) <= 0 then
        return OverseaTowerUtils.GetFirstQuestId(type)
    end
    local maxQuestId = OverseaTowerUtils.GetMaxQuestId(type)
    if checkNumber(id) >= maxQuestId then
        id = maxQuestId
    end
    return id
end



--是否通关了塔
function OverseaTowerUtils.IsPassTower(type)
    ---@type TowerQuestComponent
    local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
    local id = towerQuestComponent:GetCurrentQuestId(type)
    if checkNumber(id) <= 0 then
        return false
    end
    local maxQuestId = OverseaTowerUtils.GetMaxQuestId(type)
    if checkNumber(id) >= maxQuestId then
        id = maxQuestId
    end
    local vo = OverseaTowerUtils.GetTowerQuestVo(id)
    if checkNumber(vo.nextLevel) <= 0 or checkNumber(vo.nextLevel) > maxQuestId then
        return true
    end

    return false
end

--是否解锁收菜 
function OverseaTowerUtils.IsUnlockCollect(noTips)
    local parVo = OverseaTowerUtils.GetClimbTowerConfigVo(4)
    local id = OverseaTowerUtils.GetCurQuestId(Constants.TowerType.Main)
    local vo = OverseaTowerUtils.GetTowerQuestVo(id)

    return (checkNumber(vo.storey) > checkNumber(parVo.num)), not noTips and localize("通关卡尔森训练中枢第_num_层开启", {_num_ = parVo.num})
end

