--- 跳转时判断功能是否开启
---@param jumpId any
function OverseaTowerUtils.IsFunctionUnlock(jumpId, noTips)
    jumpId = checkNumber(jumpId)
    
    local isUnlock, unlockDesc
    if jumpId == Constants.TowerJumpId.Entry
    or jumpId == Constants.TowerJumpId.Main then
        local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(jumpId)
        local functionID = checkNumber(row:Get("functionID"))
        isUnlock = GameUtils.IsUnlockedBySystemTogId(functionID)
        if not noTips then
            unlockDesc = GameUtils.GetUnlockDescrBySystemTogId(functionID)
        end
    elseif jumpId == Constants.TowerJumpId.Red
    or jumpId == Constants.TowerJumpId.Green
    or jumpId == Constants.TowerJumpId.Blue then
        isUnlock, unlockDesc = OverseaTowerUtils.IsUnlockEmotionTower(noTips)
    elseif jumpId == Constants.TowerJumpId.Collector then
        isUnlock, unlockDesc = OverseaTowerUtils.IsUnlockCollect(noTips)
    else
        isUnlock = false
        if not noTips then
            unlockDesc = localize("功能未解锁")
        end 
        printError("未找到对应的爬塔跳转id:".. tostring(jumpId))
    end
    return isUnlock, unlockDesc
end

--- 判断跳转id是否是跳转到爬塔功能
---@param jumpId any
function OverseaTowerUtils.IsJumpToTower(jumpId)
    if jumpId == Constants.TowerJumpId.Entry
    or jumpId == Constants.TowerJumpId.Main
    or jumpId == Constants.TowerJumpId.Red
    or jumpId == Constants.TowerJumpId.Green
    or jumpId == Constants.TowerJumpId.Blue
    or jumpId == Constants.TowerJumpId.Collector then
        return true
    else
        return false
    end
end

--是否收菜满了
function OverseaTowerUtils.IsMaxCollect()
    local parVo = OverseaTowerUtils.GetClimbTowerConfigVo(3)
    local num = checkNumber(parVo.num) * 3600

    local TowerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
    local time = TowerQuestComponent:GetHookTime()
    return (time >= num)
end

function OverseaTowerUtils.GetAllReward()
    local id = OverseaTowerUtils.GetCurQuestId(Constants.TowerType.Main)
    ---@type TowerQuestRewardVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting971, "TowerQuestRewardVo", id)
    local t = CfUtils.GetCf(AutoIds.IdSetting971, "TowerQuestRewardVo", true)
    local _t = {
        {time = checkNumber(vo.revenueRewardsTime[1]), num = 0},
        {time = checkNumber(vo.revenueRewardsTime[2]), num = 0},
        {time = checkNumber(vo.revenueRewardsTime[3]), num = 0},
    }
    local maxId = OverseaTowerUtils.GetMaxQuestId(Constants.TowerType.Main)
    local isPassed = OverseaTowerUtils.IsPassQuest(id)
    for k, v in pairs(t) do
        if checkNumber(id) == maxId and isPassed then
            if checkNumber(v.id) <=  checkNumber(id) then
                _t[1].num = _t[1].num + checkNumber(v.revenueRewardsNum[1])
                _t[2].num = _t[2].num + checkNumber(v.revenueRewardsNum[2])
                _t[3].num = _t[3].num + checkNumber(v.revenueRewardsNum[3])
            end
        else
            if checkNumber(v.id) <  checkNumber(id) then
                _t[1].num = _t[1].num + checkNumber(v.revenueRewardsNum[1])
                _t[2].num = _t[2].num + checkNumber(v.revenueRewardsNum[2])
                _t[3].num = _t[3].num + checkNumber(v.revenueRewardsNum[3])
            end
        end
    end
    return _t
end

function OverseaTowerUtils.GetQuestTotalReward(questId)
    ---@type TowerQuestRewardVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting971, "TowerQuestRewardVo", questId)
    local t = CfUtils.GetCf(AutoIds.IdSetting971, "TowerQuestRewardVo", true)
    local _t = {
        {time = checkNumber(vo.revenueRewardsTime[1]), num = 0},
        {time = checkNumber(vo.revenueRewardsTime[2]), num = 0},
        {time = checkNumber(vo.revenueRewardsTime[3]), num = 0},
    }
    for k, v in pairs(t) do
        if checkNumber(v.id) <= checkNumber(questId) then
            _t[1].num = _t[1].num + checkNumber(v.revenueRewardsNum[1])
            _t[2].num = _t[2].num + checkNumber(v.revenueRewardsNum[2])
            _t[3].num = _t[3].num + checkNumber(v.revenueRewardsNum[3])
        end
    end
    return _t
end

function OverseaTowerUtils.RequestUnlockNextQuest(nextQuestId, callback)
    ---@type TowerQuestVo
    local questVo = OverseaTowerUtils.GetTowerQuestVo(nextQuestId)
    if isNull(questVo) then
        return
    end
    local towerType = questVo.type
    local questId = OverseaTowerUtils.GetCurQuestId(towerType)
    if checkNumber(questVo.unlockNum) >= questId then
        GameUtils.Toast(localize("请先解锁并通关前一关卡"))
        return
    end
    ---@type GoodsVo
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(questVo.unlockItem)
    local haveNo = GoodsUtils.GetThingNo(questVo.unlockItem)
    if checkNumber(questVo.unlockItemNum) > haveNo then
        GameUtils.Toast(localize('_name_不足不能解锁', { _name_ = vo.name }))
        return
    end
    GameUtils.Request(Interfaces.OverseaClimbingTowerUnlockTypeQuest, { type = checkNumber(towerType) }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            ---解锁完成
            GoodsUtils.DrawRewards({
                { goodsId = vo.id, num = -checkNumber(questVo.unlockItemNum) }
            })
            ---更新缓存数据
            ---@type TowerQuestComponent
            local towerQuestComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
            towerQuestComponent:UpdateQuestProgress()
            ---刷新ui
            towerQuestComponent:UnlockWorkerTowerQuest(checkNumber(nextQuestId))
            if isNotNull(callback) then
                callback()
            end
        end
    end)
end

return OverseaTowerUtils
